     1	//! The MHPCO price list: what each insurable item costs to cover, before any
     2	//! risk assessment or customer standing is taken into account.
     3	//!
     4	//! This is the catalog side of the office's knowledge. It changes when the
     5	//! MHPCO revises its prices or its building-block offer, independently of the
     6	//! underwriting rules that surcharge and discount a policy.
     7	
     8	use std::collections::BTreeMap;
     9	
    10	use crate::Item;
    11	
    12	const COMPONENT_BLOCK_SIZE: usize = 3;
    13	const COMPONENT_BLOCK_BASE_PREMIUM: f64 = 60.0;
    14	
    15	/// One entry in the MHPCO price list: what an item of this kind costs to
    16	/// cover, and what the office insures it for. The two travel together because
    17	/// they are one row of the list -- the office revises a price-list entry as a
    18	/// whole -- and because the kind decides how the item is priced in a policy.
    19	struct Listing {
    20	    base_premium: f64,
    21	    insurance_value: i64,
    22	    /// Components are the small insurable parts the MHPCO lists apart from
    23	    /// main items: they are priced per component and may form building blocks.
    24	    is_component: bool,
    25	}
    26	
    27	const SWORD: Listing = Listing {
    28	    base_premium: 100.0,
    29	    insurance_value: 1000,
    30	    is_component: false,
    31	};
    32	const AMULET: Listing = Listing {
    33	    base_premium: 60.0,
    34	    insurance_value: 600,
    35	    is_component: false,
    36	};
    37	const STAFF: Listing = Listing {
    38	    base_premium: 80.0,
    39	    insurance_value: 800,
    40	    is_component: false,
    41	};
    42	const POTION: Listing = Listing {
    43	    base_premium: 40.0,
    44	    insurance_value: 400,
    45	    is_component: false,
    46	};
    47	const COMPONENT: Listing = Listing {
    48	    base_premium: 25.0,
    49	    insurance_value: 250,
    50	    is_component: true,
    51	};
    52	
    53	/// The item's entry in the MHPCO price list.
    54	///
    55	/// An item type the price list does not name is not yet refused -- the office
    56	/// has no rule for it on the books -- so it falls through to the sword entry.
    57	fn listing_for(item: &Item) -> &'static Listing {
    58	    match item.item_type.as_str() {
    59	        "amulet" => &AMULET,
    60	        "staff" => &STAFF,
    61	        "potion" => &POTION,
    62	        "rune" | "moonstone" => &COMPONENT,
    63	        _ => &SWORD,
    64	    }
    65	}
    66	
    67	fn is_component(item: &Item) -> bool {
    68	    listing_for(item).is_component
    69	}
    70	
    71	/// A building block of alike components is offered at a special base premium.
    72	fn component_group_base_premium(count: usize) -> f64 {
    73	    if count == COMPONENT_BLOCK_SIZE {
    74	        COMPONENT_BLOCK_BASE_PREMIUM
    75	    } else {
    76	        count as f64 * COMPONENT.base_premium
    77	    }
    78	}
    79	
    80	/// Components are alike when they are of the very same type: the MHPCO reads
    81	/// "3 alike components" strictly, so runes and moonstones never share a block.
    82	fn alike_component_kind(item: &Item) -> &str {
    83	    item.item_type.as_str()
    84	}
    85	
    86	/// The base premium of all components in a policy: components of the same kind
    87	/// are counted together so that their building block can apply.
    88	fn components_base_premium(items: &[Item]) -> f64 {
    89	    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
    90	    for item in items.iter().filter(|item| is_component(item)) {
    91	        *counts.entry(alike_component_kind(item)).or_default() += 1;
    92	    }
    93	    counts.into_values().map(component_group_base_premium).sum()
    94	}
    95	
    96	/// The base premium of all main items in a policy, straight from the price list.
    97	fn main_items_base_premium(items: &[Item]) -> f64 {
    98	    items
    99	        .iter()
   100	        .filter(|item| !is_component(item))
   101	        .map(|item| listing_for(item).base_premium)
   102	        .sum()
   103	}
   104	
   105	/// The policy base premium: the sum of the base premiums of all insured items.
   106	pub(crate) fn policy_base_premium(items: &[Item]) -> f64 {
   107	    main_items_base_premium(items) + components_base_premium(items)
   108	}
   109	
   110	/// The base premium an item-specific modifier is measured against: the item's
   111	/// own listed price, which for a component is the per-component premium.
   112	pub(crate) fn item_base_premium(item: &Item) -> f64 {
   113	    listing_for(item).base_premium
   114	}
   115	
   116	/// The insurance sum of a policy: the sum of its items' insurance values.
   117	/// Unlike the premium, the insurance sum knows nothing of building blocks --
   118	/// three alike components are insured for three times a component's value.
   119	pub(crate) fn insurance_sum(items: &[Item]) -> i64 {
   120	    items
   121	        .iter()
   122	        .map(|item| listing_for(item).insurance_value)
   123	        .sum()
   124	}
